	"result_code" text,
	CONSTRAINT "platform_audit_events_actor_kind_check" CHECK ("platform_audit_events"."actor_kind" IN ('HUMAN', 'BOOTSTRAP')),
	CONSTRAINT "platform_audit_events_outcome_check" CHECK ("platform_audit_events"."outcome" IN ('SUCCEEDED', 'DENIED', 'FAILED')),
	CONSTRAINT "platform_audit_events_actor_check" CHECK (("platform_audit_events"."actor_kind" = 'HUMAN') = ("platform_audit_events"."actor_user_id" IS NOT NULL)),
	CONSTRAINT "platform_audit_events_codes_check" CHECK ("platform_audit_events"."action" ~ '^[a-z_.]{1,64}$' AND ("platform_audit_events"."permission" IS NULL OR "platform_audit_events"."permission" ~ '^[a-z_.]{1,64}$') AND ("platform_audit_events"."result_code" IS NULL OR "platform_audit_events"."result_code" ~ '^[A-Z_]{1,64}$')),
	CONSTRAINT "platform_audit_events_approval_ref_check" CHECK ("platform_audit_events"."approval_ref" IS NULL OR "platform_audit_events"."approval_ref" ~ '^[A-Za-z0-9._:-]{1,64}$')
);
