-- Hand-written (C1A): a grant is inserted ACTIVE, later changes only ACTIVE -> REVOKED (nothing else changes), and is never
-- deleted, so the single BOOTSTRAP row is permanent. granted_at and revoked_at are clock_timestamp() at the write, taken while
-- the platform-roles lock is held, so their order is the order in which grants and revocations were serialized.
CREATE FUNCTION platform_operator_roles_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP = 'DELETE' THEN
		RAISE EXCEPTION 'platform_operator_roles: grants are never deleted' USING ERRCODE = 'check_violation';
	ELSIF TG_OP = 'INSERT' THEN
		IF NEW.status <> 'ACTIVE' THEN
			RAISE EXCEPTION 'platform_operator_roles: a grant is inserted ACTIVE' USING ERRCODE = 'check_violation';
		END IF;
		NEW.granted_at := clock_timestamp();
		RETURN NEW;
	END IF;
	IF OLD.status <> 'ACTIVE' OR NEW.status <> 'REVOKED' OR NEW.revoked_by_user_id IS NULL
		OR (NEW.id, NEW.user_id, NEW.role, NEW.grant_kind, NEW.granted_by_user_id, NEW.verification_ref, NEW.granted_at)
			IS DISTINCT FROM (OLD.id, OLD.user_id, OLD.role, OLD.grant_kind, OLD.granted_by_user_id, OLD.verification_ref, OLD.granted_at) THEN
		RAISE EXCEPTION 'platform_operator_roles: the only change is ACTIVE -> REVOKED' USING ERRCODE = 'check_violation';
	END IF;
	NEW.revoked_at := clock_timestamp();
	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER platform_operator_roles_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "platform_operator_roles" FOR EACH ROW EXECUTE FUNCTION platform_operator_roles_guard();
--> statement-breakpoint
-- Hand-written (C1A): the audit is insert-only and its time is the database clock.
CREATE FUNCTION platform_audit_events_guard() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF TG_OP <> 'INSERT' THEN
		RAISE EXCEPTION 'platform_audit_events is append-only: % is not allowed', TG_OP USING ERRCODE = 'check_violation';
	END IF;
	NEW.occurred_at := now();
	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER platform_audit_events_guard_trg BEFORE INSERT OR UPDATE OR DELETE ON "platform_audit_events" FOR EACH ROW EXECUTE FUNCTION platform_audit_events_guard();
