-- Hand-written (C1A): the CREDENTIAL GENERATION. Every change of a stored password (Better Auth, tenant reset, provisioning,
-- own change) increments user_security_state.credential_generation in the same statement's transaction. No caller sets it.
CREATE FUNCTION accounts_credential_generation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
	IF NEW.password IS DISTINCT FROM OLD.password THEN
		-- Serializes with session issuance (which takes the users row FOR KEY SHARE first): a session insert either commits
		-- before this change (and is deleted by the writer's session revocation) or sees the new generation and is refused.
		PERFORM 1 FROM users WHERE id = NEW.user_id FOR UPDATE;
		INSERT INTO user_security_state (user_id, credential_generation) VALUES (NEW.user_id, 1)
		ON CONFLICT (user_id) DO UPDATE SET credential_generation = user_security_state.credential_generation + 1, updated_at = now();
	END IF;
	RETURN NULL;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER accounts_credential_generation_trg AFTER UPDATE OF password ON "accounts" FOR EACH ROW EXECUTE FUNCTION accounts_credential_generation();
--> statement-breakpoint
-- Hand-written (C1A): a session is a compare-and-swap on the credential generation. The session-create hook re-verifies the
-- password against the CURRENT credential and stamps the generation and the database time it read with it; this trigger
-- refuses the insert if the generation has moved since (a superseded password proof). Its users row lock orders it against
-- every credential change (accounts_credential_generation locks that row FOR UPDATE). created_at is the database clock at
-- insert; the binding columns and created_at never change afterwards. A proof older than one minute cannot create a session.
CREATE FUNCTION sessions_credential_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
	current_generation bigint;
BEGIN
	IF TG_OP = 'UPDATE' THEN
		NEW.created_at := OLD.created_at;
		NEW.credential_generation := OLD.credential_generation;
		NEW.credential_verified_at := OLD.credential_verified_at;
		RETURN NEW;
	END IF;
	NEW.created_at := clock_timestamp();
	-- Conflicts with the users FOR UPDATE every credential change takes (accounts_credential_generation) and is the first
	-- lock taken here, so every path locks users before user_security_state (no deadlock).
	PERFORM 1 FROM users WHERE id = NEW.user_id FOR KEY SHARE;
	SELECT coalesce((SELECT credential_generation FROM user_security_state WHERE user_id = NEW.user_id), 0)
		INTO current_generation;
	IF NEW.credential_generation IS DISTINCT FROM current_generation THEN
		RAISE EXCEPTION 'sessions: the password proof is for a superseded credential' USING ERRCODE = 'check_violation';
	END IF;
	IF NEW.credential_verified_at IS NOT NULL AND (NEW.credential_verified_at > clock_timestamp()
		OR NEW.credential_verified_at < clock_timestamp() - interval '1 minute') THEN
		RAISE EXCEPTION 'sessions: the password proof time is not plausible' USING ERRCODE = 'check_violation';
	END IF;
	RETURN NEW;
END;
$$;
--> statement-breakpoint
CREATE TRIGGER sessions_credential_guard_trg BEFORE INSERT OR UPDATE ON "sessions" FOR EACH ROW EXECUTE FUNCTION sessions_credential_guard();
